    # Markers copy their color along the row/column direction encoded by the
    # opposite-corner guides; paired markers are thickened to 2-cell tracks.
    twos = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    for r,c in twos:
        for x in range(c+1,w):
            if grid[r][x] == 5: out[r][x] = 9
        if c > 0 and grid[r][c-1] == 5: out[r][c-1] = 4
    # Corner 9 pairs extend down from top-right and up from bottom-left,
    # thickening each into a 2-wide strip through the center.
    top = next((r for r in range(h) if grid[r][-2:] == [9,9]), None)
    bot = next((r for r in range(h-1,-1,-1) if grid[r][:2] == [9,9]), None)
    if top is not None:
        for r in range(top+1, h):
            for c in (w-2,w-1):
                if grid[r][c] == 5: out[r][c] = 9
    if bot is not None:
        for r in range(0, bot):
            for c in (0,1):
                if grid[r][c] == 5: out[r][c] = 9
    return out

